1	// This file implements the organization-scoped audit chain. Every successful
2	// policy publish or rollback, and every Decide called with a non-empty
3	// decision organization, leaves an immutable record in that organization.
4	//
5	// Records carry an organization-local sequence starting at 1 and a SHA-256
6	// fingerprint that chains each record to the previous one. The genesis
7	// fingerprint binds the organization name, so records from another
8	// organization can never validate as part of this chain even when the
9	// sequence numbers and identifiers coincide.
10	package darksafe
11	
12	import (
13		"crypto/sha256"
14		"encoding/binary"
15		"encoding/hex"
16		"encoding/json"
17		"errors"
18		"fmt"
19		"unicode/utf8"
20	)
21	
22	// Audit record categories.
23	const (
24		// AuditPolicyChange is a successful publish or rollback.
25		AuditPolicyChange = "policy_change"
26		// AuditDecision is one Decide evaluation.
27		AuditDecision = "decision"
28	)
29	
30	// Sentinel errors for the audit entry points. Callers distinguish them
31	// with errors.Is; every one leaves state unchanged.
32	var (
33		// ErrInvalidPage means a page size or range argument was invalid.
34		ErrInvalidPage = errors.New("darksafe: invalid audit page")
35		// ErrInvalidRange means the upper bound is beyond what exists, the
36		// range is inverted, or a supplied fingerprint does not match.
37		ErrInvalidRange = errors.New("darksafe: invalid audit range")
38		// ErrAuditNotFound means no record exists at the requested sequence.
39		ErrAuditNotFound = errors.New("darksafe: audit record not found")
40		// ErrAuditNotADecision means the record at the sequence is not a
41		// decision record and therefore cannot be rechecked.
42		ErrAuditNotADecision = errors.New("darksafe: audit record is not a decision")
43	)
44	
45	// PolicyChange captures a successful publish or rollback.
46	type PolicyChange struct {
47		// Version is the newly created policy version.
48		Version int
49		// Policies is the full policy set of the new version.
50		Policies []Policy
51		// SourceVersion is the version copied by a rollback, and 0 for an
52		// ordinary publish.
53		SourceVersion int
54		// RolledBack reports whether the change was produced by Rollback.
55		RolledBack bool
56	}
57	
58	// DecisionRecord captures one Decide call: the full request and the
59	// decision actually returned.
60	type DecisionRecord struct {
61		Request  OrgRequest
62		Decision Decision
63	}
64	
65	// AuditRecord is one immutable entry in an organization's audit chain.
66	type AuditRecord struct {
67		Org      string
68		Seq      int // organization-local, starting at 1 and gapless
69		Kind     string
70		Change   *PolicyChange   // present when Kind == AuditPolicyChange
71		Decision *DecisionRecord // present when Kind == AuditDecision
72	
73		// PrevFingerprint is the fingerprint of the preceding record, or the
74		// genesis fingerprint for the first record.
75		PrevFingerprint string
76		// Fingerprint binds this record's full content to its predecessor.
77		Fingerprint string
78	}
79	
80	// hashEnvelope is the canonical, organization-bound representation that
81	// fingerprints are computed over. It is never exposed, so callers cannot
82	// forge one by constructing an AuditRecord with copied fields.
83	type hashEnvelope struct {
84		Org             string          `json:"org"`
85		Seq             int             `json:"seq"`
86		Kind            string          `json:"kind"`
87		Change          *PolicyChange   `json:"change,omitempty"`
88		Decision        *DecisionRecord `json:"decision,omitempty"`
89		PrevFingerprint string          `json:"prev"`
90	}
91	
92	// envelopeUsesRawBytes reports whether any string protected by the
93	// fingerprint carries bytes that are not valid UTF-8. Such envelopes are
94	// hashed through encodeCanonical instead of encoding/json, because JSON
95	// string encoding replaces invalid bytes with U+FFFD and would let two
96	// different raw contents share a fingerprint.
97	func envelopeUsesRawBytes(env *hashEnvelope) bool {
98		if !utf8.ValidString(env.Org) || !utf8.ValidString(env.Kind) ||
99			!utf8.ValidString(env.PrevFingerprint) {
100			return true
101		}
102		if env.Change != nil {
103			for _, p := range env.Change.Policies {
104				if !utf8.ValidString(p.ID) || !utf8.ValidString(p.Subject) ||
105					!utf8.ValidString(p.Action) || !utf8.ValidString(p.Scope) ||
106					!utf8.ValidString(string(p.Effect)) || !utf8.ValidString(p.ResourceID) {
107					return true
108				}
109			}
110		}
111		if env.Decision != nil {
112			req := env.Decision.Request
113			d := env.Decision.Decision
114			for _, s := range []string{
115				req.SubjectOrg, req.ResourceOrg,
116				req.Subject.ID, req.Subject.Kind, req.Resource.ID, req.Resource.Scope,
117				req.Action, d.Reason,
118			} {
119				if !utf8.ValidString(s) {
120					return true
121				}
122			}
123			for _, s := range req.Subject.Roles {
124				if !utf8.ValidString(s) {
125					return true
126				}
127			}
128			for _, s := range d.Matched {
129				if !utf8.ValidString(s) {
130					return true
131				}
132			}
133		}
134		return false
135	}
136	
137	// rawEnvelopePrefix opens every raw-byte canonical encoding. It never
138	// coincides with the start of a JSON envelope (always '{'), so
139	// fingerprints from the two encodings live in collision-free spaces.
140	const rawEnvelopePrefix = "darksafe-audit-raw-v1\x00"
141	
142	// fingerprintTag delimits one field or nested value within the canonical
143	// binary encoding. Distinct tags keep two payloads that merely share
144	// adjacent bytes apart (e.g. ["ab",""] vs ["a","b"]).
145	type fingerprintTag byte
146	
147	const (
148		tagEnvelope fingerprintTag = iota + 1
149		tagSeq
150		tagString
151		tagStringList
152		tagBool
153		tagPolicy
154		tagPolicyList
155		tagChange
156		tagSubject
157		tagResource
158		tagDecision
159		tagDecisionRecord
160	)
161	
162	// fingerprintEncoder builds the canonical byte representation of an
163	// envelope. Unlike encoding/json it writes string contents byte-for-byte
164	// with an explicit length prefix, so strings carrying invalid UTF-8 stay
165	// distinguishable: encoding/json renders both a raw 0xFF byte and a raw
166	// 0xFE byte as the U+FFFD replacement rune, collapsing genuinely
167	// different content onto identical fingerprints.
168	type fingerprintEncoder struct {
169		buf []byte
170	}
171	
172	func (e *fingerprintEncoder) tag(t fingerprintTag) {
173		e.buf = append(e.buf, byte(t))
174	}
175	
176	func (e *fingerprintEncoder) int64Tag(t fingerprintTag, v int64) {
177		e.tag(t)
178		var b [8]byte
179		binary.BigEndian.PutUint64(b[:], uint64(v))
180		e.buf = append(e.buf, b[:]...)
181	}
182	
183	func (e *fingerprintEncoder) boolTag(t fingerprintTag, v bool) {
184		e.tag(t)
185		if v {
186			e.buf = append(e.buf, 1)
187		} else {
188			e.buf = append(e.buf, 0)
189		}
190	}
191	
192	// rawString tags and writes a string from its exact memory bytes. No
193	// validation, replacement or normalization is ever performed: an invalid
194	// UTF-8 byte reaches the hash unchanged.
195	func (e *fingerprintEncoder) rawString(s string) {
196		e.tag(tagString)
197		var b [4]byte
198		binary.BigEndian.PutUint32(b[:], uint32(len(s)))
199		e.buf = append(e.buf, b[:]...)
200		e.buf = append(e.buf, s...)
201	}
202	
203	// stringList preserves nil-vs-empty explicitly: in the JSON envelope a
204	// nil slice is "null" and a non-nil empty slice is "[]", so the raw
205	// encoding must keep the two shapes apart as well.
206	func (e *fingerprintEncoder) stringList(items []string) {
207		e.tag(tagStringList)
208		if items == nil {
209			e.buf = append(e.buf, 0)
210			return
211		}
212		e.buf = append(e.buf, 1)
213		var b [4]byte
214		binary.BigEndian.PutUint32(b[:], uint32(len(items)))
215		e.buf = append(e.buf, b[:]...)
216		for _, s := range items {
217			e.rawString(s)
218		}
219	}
220	
221	func (e *fingerprintEncoder) policy(p Policy) {
222		e.tag(tagPolicy)
223		e.rawString(p.ID)
224		e.rawString(p.Subject)
225		e.rawString(p.Action)
226		e.rawString(p.Scope)
227		e.rawString(string(p.Effect))
228		e.boolTag(tagBool, p.Recursive)
229		// ResourceID is appended only when set, so the canonical byte layout
230		// of every legacy (resource-unrestricted) policy is unchanged. It
231		// pairs with the omitempty JSON tag: the two fingerprint families stay
232		// in sync about whether the field participates at all.
233		if p.ResourceID != "" {
234			e.rawString(p.ResourceID)
235		}
236	}
237	
238	func (e *fingerprintEncoder) policyList(policies []Policy) {
239		e.tag(tagPolicyList)
240		if policies == nil {
241			e.buf = append(e.buf, 0)
242			return
243		}
244		e.buf = append(e.buf, 1)
245		var b [4]byte
246		binary.BigEndian.PutUint32(b[:], uint32(len(policies)))
247		e.buf = append(e.buf, b[:]...)
248		for _, p := range policies {
249			e.policy(p)
250		}
251	}
252	
253	func (e *fingerprintEncoder) change(c *PolicyChange) {
254		e.tag(tagChange)
255		// A nil pointer is encoded as tagChange alone; a present value's
256		// fields follow immediately.
257		if c == nil {
258			return
259		}
260		e.int64Tag(tagSeq, int64(c.Version))
261		e.policyList(c.Policies)
262		e.int64Tag(tagSeq, int64(c.SourceVersion))
263		e.boolTag(tagBool, c.RolledBack)
264	}
265	
266	func (e *fingerprintEncoder) subject(su Subject) {
267		e.tag(tagSubject)
268		e.rawString(su.ID)
269		e.rawString(su.Kind)
270		e.stringList(su.Roles)
271		e.boolTag(tagBool, su.Disabled)
272	}
273	
274	func (e *fingerprintEncoder) resource(r Resource) {
275		e.tag(tagResource)
276		e.rawString(r.ID)
277		e.rawString(r.Scope)
278	}
279	
280	func (e *fingerprintEncoder) decision(d Decision) {
281		e.tag(tagDecision)
282		e.boolTag(tagBool, d.Allowed)
283		e.rawString(d.Reason)
284		e.stringList(d.Matched)
285		e.int64Tag(tagSeq, int64(d.Version))
286	}
287	
288	func (e *fingerprintEncoder) decisionRecord(d *DecisionRecord) {
289		e.tag(tagDecisionRecord)
290		if d == nil {
291			return
292		}
293		// OrgRequest fields are written inline at the same nesting depth the
294		// request occupies in the envelope; no field is skipped.
295		e.rawString(d.Request.SubjectOrg)
296		e.rawString(d.Request.ResourceOrg)
297		e.subject(d.Request.Subject)
298		e.resource(d.Request.Resource)
299		e.rawString(d.Request.Action)
300		e.decision(d.Decision)
301	}
302	
303	// encodeCanonical returns the raw bytes fingerprinted for an envelope
304	// whose strings include invalid UTF-8. Every string the record carries
305	// reaches the output byte-for-byte, at whatever nesting depth or list
306	// position it occupies. The prefix separates this encoding space from
307	// JSON fingerprints.
308	func encodeCanonical(env *hashEnvelope) []byte {
309		e := &fingerprintEncoder{buf: []byte(rawEnvelopePrefix)}
310		e.tag(tagEnvelope)
311		e.rawString(env.Org)
312		e.int64Tag(tagSeq, int64(env.Seq))
313		e.rawString(env.Kind)
314		e.change(env.Change)
315		e.decisionRecord(env.Decision)
316		e.rawString(env.PrevFingerprint)
317		return e.buf
318	}
319	
320	// genesisFingerprint derives the chain root from the organization name,
321	// keeping equal identifiers in different organizations independent.
322	func genesisFingerprint(org string) string {
323		sum := sha256.Sum256([]byte("darksafe-audit-genesis\x00" + org))
324		return hex.EncodeToString(sum[:])
325	}
326	
327	// computeFingerprint returns the fingerprint for an envelope. Records made
328	// exclusively of valid UTF-8 keep the historical JSON fingerprint, so old
329	// exports and checkpoints remain valid; records containing invalid bytes
330	// use the length-prefixed raw encoding that protects their exact bytes.
331	func computeFingerprint(env *hashEnvelope) string {
332		if envelopeUsesRawBytes(env) {
333			sum := sha256.Sum256(encodeCanonical(env))
334			return hex.EncodeToString(sum[:])
335		}
336		b, err := json.Marshal(env)
337		if err != nil {
338			// All envelope fields are plain, JSON-encodable values; a failure
339			// here indicates a programming error, not user input.
340			panic(fmt.Errorf("darksafe: audit envelope must encode: %w", err))
341		}
342		sum := sha256.Sum256(b)
343		return hex.EncodeToString(sum[:])
344	}
345	
346	// fingerprintFor builds and fingerprints the envelope for a record.
347	func fingerprintFor(r *AuditRecord) string {
348		return computeFingerprint(&hashEnvelope{
349			Org:             r.Org,
350			Seq:             r.Seq,
351			Kind:            r.Kind,
352			Change:          r.Change,
353			Decision:        r.Decision,
354			PrevFingerprint: r.PrevFingerprint,
355		})
356	}
357	
358	// clonePolicies returns a detached copy of a policy set.
359	func clonePolicies(in []Policy) []Policy {
360		if in == nil {
361			return nil
362		}
363		return append([]Policy(nil), in...)
364	}
365	
366	// cloneChange returns a detached copy of a policy-change payload.
367	func cloneChange(c *PolicyChange) *PolicyChange {
368		if c == nil {
369			return nil
370		}
371		cp := *c
372		cp.Policies = clonePolicies(c.Policies)
373		return &cp
374	}
375	
376	// cloneDecision returns a detached copy of a decision payload.
377	func cloneDecision(d *DecisionRecord) *DecisionRecord {
378		if d == nil {
379			return nil
380		}
381		cp := *d
382		if len(d.Decision.Matched) > 0 {
383			cp.Decision.Matched = append([]string(nil), d.Decision.Matched...)
384		}
385		if len(d.Request.Subject.Roles) > 0 {
386			cp.Request.Subject.Roles = append([]string(nil), d.Request.Subject.Roles...)
387		}
388		return &cp
389	}
390	
391	// cloneRecord returns a fully detached copy of a record.
392	func cloneRecord(r *AuditRecord) *AuditRecord {
393		cp := *r
394		cp.Change = cloneChange(r.Change)
395		cp.Decision = cloneDecision(r.Decision)
396		return &cp
397	}
398	
399	// appendAuditLocked validates, fingerprints and stores one record. It runs
400	// under the store mutex and is the single place records are created.
401	func (st *orgState) appendAuditLocked(org, kind string, change *PolicyChange, decision *DecisionRecord) *AuditRecord {
402		seq := len(st.audit) + 1
403		prev := genesisFingerprint(org)
404		if len(st.audit) > 0 {
405			prev = st.audit[len(st.audit)-1].Fingerprint
406		}
407		// Store detached copies; later caller mutation must not reach the chain.
408		rec := &AuditRecord{
409			Org:             org,
410			Seq:             seq,
411			Kind:            kind,
412			Change:          cloneChange(change),
413			Decision:        cloneDecision(decision),
414			PrevFingerprint: prev,
415		}
416		rec.Fingerprint = fingerprintFor(rec)
417		st.audit = append(st.audit, rec)
418		return cloneRecord(rec)
419	}
420	
421	// auditHeadLocked returns the highest sequence in the chain and the
422	// fingerprint that covers it: (0, genesis) for an organization with no
423	// records.
424	func (st *orgState) auditHeadLocked(org string) (int, string) {
425		if len(st.audit) == 0 {
426			return 0, genesisFingerprint(org)
427		}
428		last := st.audit[len(st.audit)-1]
429		return last.Seq, last.Fingerprint
430	}
431	
432	// Checkpoint pins an audit query to an exact point in a chain.
433	type Checkpoint struct {
434		Org         string
435		EndSeq      int
436		Fingerprint string
437	}
438	
439	// AuditPage is one stable slice of an organization's audit chain.
440	type AuditPage struct {
441		Org     string
442		Records []AuditRecord
443		// BeginSeq/EndSeq delimit the whole pinned range, not just this page.
444		BeginSeq int
445		EndSeq   int
446		// Next is the first sequence of the following page, 0 when exhausted.
447		Next int
448		// Checkpoint is the pinned upper bound shared by every page.
449		Checkpoint Checkpoint
450	}
451	
452	// recordMatches reports whether a record survives the query filters.
453	func recordMatches(r *AuditRecord, kind, subjectID string) bool {
454		if kind != "" && r.Kind != kind {
455			return false
456		}
457		if subjectID != "" {
458			// A subject filter selects decision records of that subject only.
459			if r.Kind != AuditDecision || r.Decision == nil ||
460				r.Decision.Request.Subject.ID != subjectID {
461				return false
462			}
463		}
464		return true
465	}
466	
467	// AuditQuery pins the first page of an audit query. startSeq is the first
468	// sequence considered (1 from the beginning); endSeq <= 0 means "everything
469	// currently stored". The returned checkpoint must be passed to AuditPage
470	// for the following pages, so records appended after the first query never
471	// mix into later pages.
472	func (s *Store) AuditQuery(org string, startSeq, pageSize int, kind, subjectID string) (*AuditPage, error) {
473		if org == "" {
474			return nil, ErrMissingOrganization
475		}
476		if kind != "" && kind != AuditPolicyChange && kind != AuditDecision {
477			return nil, fmt.Errorf("%w: unknown category %q", ErrInvalidPage, kind)
478		}
479		if pageSize <= 0 {
480			return nil, fmt.Errorf("%w: page size must be positive, got %d", ErrInvalidPage, pageSize)
481		}
482		if startSeq < 1 {
483			return nil, fmt.Errorf("%w: start sequence must be >= 1, got %d", ErrInvalidPage, startSeq)
484		}
485		s.mu.Lock()
486		defer s.mu.Unlock()
487		st := s.orgLocked(org)
488		end, fingerprint := st.auditHeadLocked(org)
489		cp := Checkpoint{Org: org, EndSeq: end, Fingerprint: fingerprint}
490		if end == 0 {
491			// An organization with no records always yields the empty genesis
492			// page, regardless of where the caller asked to begin.
493			return &AuditPage{Org: org, BeginSeq: 1, EndSeq: 0, Checkpoint: cp}, nil
494		}
495		if startSeq > end {
496			return nil, fmt.Errorf("%w: start sequence %d is beyond end sequence %d", ErrInvalidRange, startSeq, end)
497		}
498		return s.auditPageLocked(org, startSeq, end, fingerprint, pageSize, kind, subjectID), nil
499	}
500	
501	// AuditPage returns one page of a previously pinned query. nextSeq is the
502	// cursor from the previous page; when it is 0 the range is exhausted. The
503	// checkpoint is re-verified against the chain on every call.
504	func (s *Store) AuditPage(cp Checkpoint, nextSeq, pageSize int, kind, subjectID string) (*AuditPage, error) {
505		if cp.Org == "" {
506			return nil, ErrMissingOrganization
507		}
508		if kind != "" && kind != AuditPolicyChange && kind != AuditDecision {
509			return nil, fmt.Errorf("%w: unknown category %q", ErrInvalidPage, kind)
510		}
511		if pageSize <= 0 {
512			return nil, fmt.Errorf("%w: page size must be positive, got %d", ErrInvalidPage, pageSize)
513		}
514		if nextSeq < 0 {
515			return nil, fmt.Errorf("%w: next sequence must be >= 0, got %d", ErrInvalidPage, nextSeq)
516		}
517		s.mu.Lock()
518		defer s.mu.Unlock()
519		st, ok := s.orgs[cp.Org]
520		if !ok {
521			// No organization state: the only valid checkpoint is an empty one.
522			g := genesisFingerprint(cp.Org)
523			if cp.EndSeq == 0 && cp.Fingerprint == g && nextSeq == 0 {
524				return &AuditPage{Org: cp.Org, BeginSeq: 0, EndSeq: 0, Checkpoint: cp}, nil
525			}
526			return nil, fmt.Errorf("%w: checkpoint organization has no records", ErrInvalidRange)
527		}
528		head := len(st.audit)
529		if cp.EndSeq < 0 || cp.EndSeq > head {
530			return nil, fmt.Errorf("%w: end sequence %d beyond %d", ErrInvalidRange, cp.EndSeq, head)
531		}
532		wantFP := genesisFingerprint(cp.Org)
533		if cp.EndSeq > 0 {
534			if cp.EndSeq > len(st.audit) {
535				return nil, fmt.Errorf("%w: end sequence %d beyond %d", ErrInvalidRange, cp.EndSeq, head)
536			}
537			wantFP = st.audit[cp.EndSeq-1].Fingerprint
538		}
539		if cp.Fingerprint != wantFP {
540			return nil, fmt.Errorf("%w: checkpoint fingerprint does not match the chain at sequence %d", ErrInvalidRange, cp.EndSeq)
541		}
542		if nextSeq == 0 {
543			return &AuditPage{Org: cp.Org, BeginSeq: 1, EndSeq: cp.EndSeq, Checkpoint: cp}, nil
544		}
545		if nextSeq > cp.EndSeq+1 {
546			return nil, fmt.Errorf("%w: next sequence %d beyond pinned range ending at %d", ErrInvalidRange, nextSeq, cp.EndSeq)
547		}
548		if nextSeq == cp.EndSeq+1 {
549			return &AuditPage{Org: cp.Org, BeginSeq: nextSeq, EndSeq: cp.EndSeq, Checkpoint: cp}, nil
550		}
551		return s.auditPageLocked(cp.Org, nextSeq, cp.EndSeq, wantFP, pageSize, kind, subjectID), nil
552	}
553	
554	// auditPageLocked scans forward collecting up to pageSize matching records
555	// and computes the next-page cursor. It does not stop at pageSize raw
556	// records: filtering happens within the pinned [start,end] window.
557	func (s *Store) auditPageLocked(org string, startSeq, endSeq int, endFP string, pageSize int, kind, subjectID string) *AuditPage {
558		st := s.orgs[org]
559		out := make([]AuditRecord, 0, pageSize)
560		i := startSeq
561		for ; i <= endSeq && len(out) < pageSize; i++ {
562			r := st.audit[i-1]
563			if recordMatches(r, kind, subjectID) {
564				out = append(out, *cloneRecord(r))
565			}
566		}
567		next := 0
568		if i <= endSeq {
569			next = i
570		}
571		return &AuditPage{
572			Org:        org,
573			Records:    out,
574			BeginSeq:   startSeq,
575			EndSeq:     endSeq,
576			Next:       next,
577			Checkpoint: Checkpoint{Org: org, EndSeq: endSeq, Fingerprint: endFP},
578		}
579	}
580	
581	// AuditExport returns detached copies of the complete records through
582	// endSeq, suitable for offline verification. endSeq <= 0 means everything
583	// currently stored. An organization with no records yields an empty slice
584	// together with its sequence-0 checkpoint.
585	func (s *Store) AuditExport(org string, endSeq int) (records []AuditRecord, cp Checkpoint, err error) {
586		if org == "" {
587			return nil, Checkpoint{}, ErrMissingOrganization
588		}
589		s.mu.Lock()
590		defer s.mu.Unlock()
591		st := s.orgLocked(org)
592		head := len(st.audit)
593		if endSeq <= 0 {
594			endSeq = head
595		}
596		if endSeq > head {
597			return nil, Checkpoint{}, fmt.Errorf("%w: end sequence %d beyond %d", ErrInvalidRange, endSeq, head)
598		}
599		if endSeq < 0 {
600			return nil, Checkpoint{}, fmt.Errorf("%w: end sequence must be >= 0, got %d", ErrInvalidPage, endSeq)
601		}
602		// The checkpoint fingerprints the final exported record, not the
603		// possibly later current head.
604		fingerprint := genesisFingerprint(org)
605		if endSeq > 0 {
606			fingerprint = st.audit[endSeq-1].Fingerprint
607		}
608		out := make([]AuditRecord, 0, endSeq)
609		for i := 0; i < endSeq; i++ {
610			out = append(out, *cloneRecord(st.audit[i]))
611		}
612		return out, Checkpoint{Org: org, EndSeq: endSeq, Fingerprint: fingerprint}, nil
613	}
614	
615	// VerifyAudit validates an exported record set entirely without a Store.
616	// The caller separately retains the organization, end sequence and
617	// fingerprint they expect. It rejects any modified field, missing middle or
618	// tail record, swapped order, and record spliced in from another
619	// organization. Empty or nil records validate exactly when the checkpoint
620	// is the organization's genesis (end sequence 0).
621	func VerifyAudit(org string, records []AuditRecord, cp Checkpoint) error {
622		if org == "" {
623			return ErrMissingOrganization
624		}
625		if cp.Org != "" && cp.Org != org {
626			return fmt.Errorf("%w: checkpoint organization %q does not match %q", ErrInvalidRange, cp.Org, org)
627		}
628		genesis := genesisFingerprint(org)
629		if len(records) == 0 {
630			if cp.EndSeq != 0 || cp.Fingerprint != genesis {
631				return fmt.Errorf("%w: empty records but checkpoint claims end sequence %d", ErrInvalidRange, cp.EndSeq)
632			}
633			return nil
634		}
635		if cp.EndSeq != len(records) {
636			return fmt.Errorf("%w: have %d records, checkpoint ends at %d", ErrInvalidRange, len(records), cp.EndSeq)
637		}
638		prev := genesis
639		for i, r := range records {
640			wantSeq := i + 1
641			if r.Org != org {
642				return fmt.Errorf("%w: record %d belongs to organization %q", ErrInvalidRange, wantSeq, r.Org)
643			}
644			if r.Seq != wantSeq {
645				return fmt.Errorf("%w: record %d has sequence %d", ErrInvalidRange, wantSeq, r.Seq)
646			}
647			if r.PrevFingerprint != prev {
648				return fmt.Errorf("%w: record %d breaks the chain", ErrInvalidRange, wantSeq)
649			}
650			wantFP := fingerprintFor(&r)
651			if r.Fingerprint != wantFP {
652				return fmt.Errorf("%w: record %d fingerprint mismatch", ErrInvalidRange, wantSeq)
653			}
654			if r.Kind == AuditPolicyChange {
655				if r.Change == nil || r.Decision != nil {
656					return fmt.Errorf("%w: record %d payload does not match its category", ErrInvalidRange, wantSeq)
657				}
658			} else if r.Kind == AuditDecision {
659				if r.Decision == nil || r.Change != nil {
660					return fmt.Errorf("%w: record %d payload does not match its category", ErrInvalidRange, wantSeq)
661				}
662			} else {
663				return fmt.Errorf("%w: record %d has unknown category %q", ErrInvalidRange, wantSeq, r.Kind)
664			}
665			prev = r.Fingerprint
666		}
667		last := records[len(records)-1]
668		if last.Fingerprint != cp.Fingerprint {
669			return fmt.Errorf("%w: checkpoint fingerprint does not match the final record", ErrInvalidRange)
670		}
671		return nil
672	}
673	
674	// RecheckDecision re-evaluates the request stored in an organization's
675	// decision record against the policy version that decision actually used.
676	// Later publishes or rollbacks cannot alter the result. Non-decision
677	// records and missing sequences return distinguishable errors.
678	func (s *Store) RecheckDecision(org string, seq int) (Decision, error) {
679		if org == "" {
680			return Decision{}, ErrMissingOrganization
681		}
682		if seq < 1 {
683			return Decision{}, fmt.Errorf("%w: sequence %d", ErrAuditNotFound, seq)
684		}
685		s.mu.Lock()
686		defer s.mu.Unlock()
687		st, ok := s.orgs[org]
688		if !ok || seq > len(st.audit) {
689			return Decision{}, fmt.Errorf("%w: organization %q has no audit sequence %d", ErrAuditNotFound, org, seq)
690		}
691		rec := st.audit[seq-1]
692		if rec.Kind != AuditDecision || rec.Decision == nil {
693			return Decision{}, fmt.Errorf("%w: sequence %d is %s", ErrAuditNotADecision, seq, rec.Kind)
694		}
695		req := rec.Decision.Request
696		version := rec.Decision.Decision.Version
697		if version == 0 {
698			// The original decision evaluated no published version: requests
699			// rejected at the envelope, or an organization with no publish yet.
700			if d, ok := checkRequest(org, req); !ok {
701				return d, nil
702			}
703			return Decision{Allowed: false, Reason: "organization has no published version"}, nil
704		}
705		src, ok := st.versions[version]
706		if !ok {
707			// A decision's version is immutable and never deleted; its absence
708			// indicates store tampering rather than normal operation.
709			return Decision{}, fmt.Errorf("%w: decision used version %d, which no longer exists", ErrVersionNotFound, version)
710		}
711		return evaluate(req, append([]Policy(nil), src...), version), nil
712	}
713

