83		original := cloneDecisionValue(rec.Decision.Decision)
84		req := rec.Decision.Request
85		if len(req.Subject.Roles) > 0 {
86			req.Subject.Roles = append([]string(nil), req.Subject.Roles...)
87		}
88		version := original.Version
89	
90		var recomputed Decision
91		if version == 0 {
92			// The original evaluation used no published version: replay the
93			// envelope rejections exactly, then the not-yet-published denial.
94			if d, ok := checkRequest(org, req); !ok {
95				recomputed = d
96			} else {
97				recomputed = Decision{Allowed: false, Reason: "organization has no published version"}
98			}
99		} else {
100			// The version's full content must travel in a same-organization
