102			// comes first: a request the envelope rejects must not mask a
103			// missing version with an ordinary denial result.
104			policies, found := policiesBefore(records, seq-1, version)
105			if !found {
106				if _, later := policiesBefore(records, len(records), version); later {
107					return OfflineDecisionReview{}, fmt.Errorf(
108						"%w: decision at sequence %d used version %d, whose change record appears only after it",
109						ErrVersionNotFound, seq, version)
110				}
111				return OfflineDecisionReview{}, fmt.Errorf(
112					"%w: decision at sequence %d used version %d, which has no policy change record in the export",
113					ErrVersionNotFound, seq, version)
114			}
115			// The version exists as claimed, but chain integrity does not imply
116			// the request was admissible: re-run the same envelope checks the
117			// online decision runs before any policy is consulted. A rejection
118			// here evaluates no policies, hence version 0 and no matches, even
119			// when the version holds a fully matching allow policy.
120			if d, ok := checkRequest(org, req); !ok {
121				recomputed = d
122			} else {
