136	// published version and returns a detached copy of its full content. The
137	// gapless chain validation guarantees records are in sequence order.
138	func policiesBefore(records []AuditRecord, limit, version int) ([]Policy, bool) {
139		for i := 0; i < limit; i++ {
140			r := &records[i]
141			if r.Kind != AuditPolicyChange || r.Change == nil {
142				continue
143			}
144			if r.Change.Version == version {
145				return append([]Policy(nil), r.Change.Policies...), true
146			}
147		}
148		return nil, false
149	}
