161	// empty matched list describe the same set of hits.
162	func decisionsEqual(a, b Decision) bool {
163		if a.Allowed != b.Allowed || a.Reason != b.Reason || a.Version != b.Version {
164			return false
165		}
166		if len(a.Matched) == 0 && len(b.Matched) == 0 {
167			return true
168		}
169		if len(a.Matched) != len(b.Matched) {
170			return false
171		}
172		for i := range a.Matched {
173			if a.Matched[i] != b.Matched[i] {
174				return false
175			}
176		}
177		return true
178	}
