	}
	m2, _, err := s.AuditExport("acme", 0)
	if err != nil {
		t.Fatal(err)
	}
	r1 := recordBySeq(t, m1, 2)
	r2 := recordBySeq(t, m2, 2)
	if r1.Decision.Request.Subject.Roles == nil {
		t.Fatal("premise: explicitly empty roles should be non-nil")
	}
	r1.Decision.Request.Subject.Roles = append(r1.Decision.Request.Subject.Roles, "临时角色甲")
	r2.Decision.Request.Subject.Roles = append(r2.Decision.Request.Subject.Roles, "临时角色乙")
	t.Logf("after appends: m1=%v m2=%v decision=%v",
		r1.Decision.Request.Subject.Roles, r2.Decision.Request.Subject.Roles, d)
	if !reflect.DeepEqual(r1.Decision.Request.Subject.Roles, []string{"临时角色甲"}) {
		t.Errorf("material 1 roles = %v, want [临时角色甲]", r1.Decision.Request.Subject.Roles)
	}
	if !reflect.DeepEqual(r2.Decision.Request.Subject.Roles, []string{"临时角色乙"}) {
		t.Errorf("material 2 roles = %v, want [临时角色乙]", r2.Decision.Request.Subject.Roles)
	}

	// Appending to the originally submitted list must not reach storage.
	req.Subject.Roles = append(req.Subject.Roles, "原始追加")
	fresh, _, _ := s.AuditExport("acme", 0)
	fr := recordBySeq(t, fresh, 2)
	if len(fr.Decision.Request.Subject.Roles) != 0 || fr.Decision.Request.Subject.Roles == nil {
		t.Errorf("stored roles = %v, want non-nil empty", fr.Decision.Request.Subject.Roles)
	}
}

